use std::time::Duration;

use crate::state::{AppState, State};
use anyhow::Result;
use tokio::{runtime::Handle, task::JoinHandle};

pub struct Logic {
    state: State,
}

impl Logic {
    pub fn new(state: State) -> Self {
        Self { state }
    }

    pub fn spawn(self, runtime: &Handle) -> JoinHandle<Result<()>> {
        runtime.spawn(self.main())
    }

    async fn main(mut self) -> Result<()> {
        self.state.set_app_state(AppState::Login)?;
        self.state.set_login("ABCD-EFGH".into())?;

        tokio::time::sleep(Duration::from_secs(30)).await;
        self.state.set_app_state(AppState::Ready)?;

        self.state
            .set_track("Honestly", "THØRNS, Kasane Teto", 2024, 218)?;

        self.state
            .set_artwork("https://i.scdn.co/image/ab67616d0000b27340a96de45049b6714636ef2d")
            .await?;

        self.state.set_lyrics(vec![
            String::from("Line 1"),
            String::from("Line 2 but its longer"),
            String::from(
                "Line 3 and its reeeaaaalllly long WOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOO hi",
            ),
            String::from(
                "",
            ),
        ])?;

        self.state.sync_progress(0.4)?;
        self.state.sync_playing(true)?;

        loop {
            self.state.wait_event().await?;
        }
    }
}
